def shortestPathLength(graph: list[list[int]]) -> int:
    n = len(graph)
    if n <= 1: return 0
    from collections import deque
    target_mask = (1 << n) - 1
    q = deque([(i, 1 << i, 0) for i in range(n)])
    visited = {(i, 1 << i) for i in range(n)}
    while q:
        u, mask, dist = q.popleft()
        if mask == target_mask: return dist
        for v in graph[u]:
            nxt_mask = mask | (1 << v)
            if (v, nxt_mask) not in visited:
                visited.add((v, nxt_mask))
                q.append((v, nxt_mask, dist + 1))
    return 0

